// SourceFile identifies the raw file an activity was derived from.
type SourceFile struct {
	ActivityID int64
	Key        string
	SHA256     string
	Origin     string
}

// Outdated returns the FIT recordings derived with an analysis version
// older than version, oldest activity first.
func (s *Store) Outdated(ctx context.Context, version int) ([]SourceFile, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT a.id, src.source_key, COALESCE(src.sha256, ''), COALESCE(src.origin, '')
		FROM activity a JOIN activity_source src ON src.activity_id = a.id AND src.source = 'fit'
		WHERE a.analysis_version < ? ORDER BY a.start_time`, version)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []SourceFile
	for rows.Next() {
		var f SourceFile
		if err := rows.Scan(&f.ActivityID, &f.Key, &f.SHA256, &f.Origin); err != nil {
			return nil, err
		}
		out = append(out, f)
	}
	return out, rows.Err()
}
